def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    opp_coops = sum(1 for h in history if h[1] == 'C')
    first_def = -1
    for i, (me, opp) in enumerate(history):
        if me == 'D':
            first_def = i
            break
    if first_def == -1:
        if opp_coops == n:
            if n >= 3:
                return 'D'
            return 'C'
        else:
            last_opp = history[-1][1]
            last_me = history[-1][0]
            opp_rate = opp_coops / float(n)
            if last_opp == 'D':
                if opp_rate > 0.6 and rng.random() < 0.8:
                    return 'C'
                return 'D'
            else:
                if last_me == 'D':
                    return 'C'
                return 'C'
    else:
        if opp_coops == n:
            if n == first_def + 1:
                return 'C'
            else:
                return 'D'
        else:
            last_opp = history[-1][1]
            last_me = history[-1][0]
            opp_rate = opp_coops / float(n)
            if last_opp == 'D':
                if opp_rate > 0.6 and rng.random() < 0.8:
                    return 'C'
                return 'D'
            else:
                if last_me == 'D':
                    return 'C'
                return 'C'
